"""Resolve job title from page signals; soft-filter obviously non-matching titles."""

from __future__ import annotations

import re
import time

from v2.shared.observability.sli_observe import passed, reject, sli_observe
from v2.shared.patterns.worker_runtime import ExecutionResult
from v2.workers.job_matcher.agent.title_matcher import title_words

MODULE_NAME = "job_matcher__resolve_title"
MODULE_TYPE = "filter"
REJECTION_REASONS = {"TITLE_NOT_IN_PROFILE"}
ERROR_REASONS: set[str] = set()
WARNING_REASONS: set[str] = set()

_TAG_SPLIT_RE = re.compile(r"[|\-–—]")


def _resolve_title(row: dict) -> str:
    """Priority: structured_job.title > title_tag (first segment) > h1 > scraped.title."""
    page = row.get("page") or {}
    sj = page.get("structured_job") or {}

    structured = (sj.get("title") or "").strip()
    if structured:
        return structured

    tag = (page.get("title_tag") or "").strip()
    if tag:
        return _TAG_SPLIT_RE.split(tag)[0].strip()

    h1 = (page.get("h1") or "").strip()
    if h1:
        return h1

    return row.get("title", "").strip()


def _build_profile_title_words(titles: list) -> frozenset[str]:
    """Union of all word tokens from every profile title."""
    tokens: set[str] = set()
    for t in titles:
        name = t.get("title", "") if isinstance(t, dict) else str(t)
        tokens.update(title_words(name))
    return frozenset(tokens)


def main(context: dict, prev_data: list[dict]) -> ExecutionResult:
    trace_id: str = context.get("trace_id")
    start_time = time.time()

    profile_title_words = _build_profile_title_words(context["profile"].get("titles") or [])

    for row in prev_data:
        resolved = _resolve_title(row)
        row["resolved_title"] = resolved
        job_words = title_words(resolved)
        if not job_words or not (job_words & profile_title_words):
            reject(row, "TITLE_NOT_IN_PROFILE")

    sli_observe(prev_data, MODULE_NAME, start_time, trace_id)
    return ExecutionResult(
        trace_id=trace_id,
        script_span_id=f"{MODULE_NAME}_{trace_id}",
        data=passed(prev_data),
        artifacts={},
        metrics={},
    )

"""Collect location strings; soft-filter rows with no plausible profile city match."""

from __future__ import annotations

import re
import time

from v2.shared.observability.sli_observe import passed, reject, sli_observe
from v2.shared.patterns.worker_runtime import ExecutionResult

MODULE_NAME = "job_matcher__resolve_location"
MODULE_TYPE = "filter"
REJECTION_REASONS = {"LOCATION_NOT_IN_PROFILE"}
ERROR_REASONS: set[str] = set()
WARNING_REASONS: set[str] = set()

_PLACEHOLDER_RE = re.compile(r"^\d+\s+location", re.IGNORECASE)
_REMOTE_RE = re.compile(r"\b(remote|home.based|work from home|wfh|home based)\b", re.IGNORECASE)


def _collect_location_strings(row: dict) -> list[str]:
    """Gather all location text from all structured_job location fields and scraped.location."""
    strings: list[str] = []
    page = row.get("page") or {}
    sj = page.get("structured_job") or {}

    # sj.locations (array) — used by some job pages
    for loc in sj.get("locations") or []:
        if loc and str(loc).strip():
            strings.append(str(loc).strip())

    # sj.location (singular string) + sj.additional_locations (array) — used by others
    sj_loc = (sj.get("location") or "").strip()
    if sj_loc:
        strings.append(sj_loc)
    for loc in sj.get("additional_locations") or []:
        if loc and str(loc).strip():
            strings.append(str(loc).strip())

    # scraped.location, skip "N Locations" placeholder
    scraped = (row.get("location") or "").strip()
    if scraped and not _PLACEHOLDER_RE.match(scraped):
        strings.append(scraped)

    return strings


def _build_profile_city_set(locations: list) -> frozenset[str]:
    """All city names from profile locations (name + includes), lower-cased."""
    cities: set[str] = set()
    for loc in locations:
        cities.add((loc.get("name") or "").lower())
        for inc in loc.get("includes") or []:
            if inc:
                cities.add(inc.lower())
    return frozenset(c for c in cities if c)


def _has_city_token(strings: list[str], profile_cities: frozenset[str]) -> bool:
    """True if any token from any location string appears in the profile city set."""
    for s in strings:
        for token in re.split(r"[\s,/|]+", s.lower()):
            token = token.strip()
            if token and token in profile_cities:
                return True
    return False


def main(context: dict, prev_data: list[dict]) -> ExecutionResult:
    trace_id: str = context.get("trace_id")
    start_time = time.time()

    profile_cities = _build_profile_city_set(context["profile"].get("locations") or [])
    has_remote_profile = any(loc.get("type") == "remote" for loc in context["profile"].get("locations") or [])

    for row in prev_data:
        strings = _collect_location_strings(row)
        row["location_strings"] = strings

        is_remote = any(_REMOTE_RE.search(s) for s in strings)
        row["is_remote_hint"] = is_remote

        if is_remote and has_remote_profile:
            continue
        if _has_city_token(strings, profile_cities):
            continue
        reject(row, "LOCATION_NOT_IN_PROFILE")

    sli_observe(prev_data, MODULE_NAME, start_time, trace_id)
    return ExecutionResult(
        trace_id=trace_id,
        script_span_id=f"{MODULE_NAME}_{trace_id}",
        data=passed(prev_data),
        artifacts={},
        metrics={},
    )

"""Resolve company name from page signals; soft-filter obviously non-matching companies."""

from __future__ import annotations

import time

from v2.shared.observability.sli_observe import passed, reject, sli_observe
from v2.shared.patterns.worker_runtime import ExecutionResult
from v2.workers.job_matcher.agent.company_matcher import normalize_company

MODULE_NAME = "job_matcher__resolve_company"
MODULE_TYPE = "filter"
REJECTION_REASONS = {"COMPANY_NOT_IN_PROFILE"}
ERROR_REASONS: set[str] = set()
WARNING_REASONS: set[str] = set()


def _resolve_company_name(row: dict) -> str:
    """Priority: structured_job.company > scraped.company."""
    page = row.get("page") or {}
    sj = page.get("structured_job") or {}
    structured = (sj.get("company") or "").strip()
    if structured:
        return structured
    return row.get("company", "").strip()


def _build_profile_tokens(companies: list) -> frozenset[str]:
    """Union of all normalised tokens from every profile company."""
    tokens: set[str] = set()
    for c in companies:
        name = c.get("name", "") if isinstance(c, dict) else str(c)
        tokens.update(normalize_company(name))
    return frozenset(tokens)


def main(context: dict, prev_data: list[dict]) -> ExecutionResult:
    trace_id: str = context.get("trace_id")
    start_time = time.time()

    profile_tokens = _build_profile_tokens(context["profile"].get("companies") or [])

    for row in prev_data:
        resolved = _resolve_company_name(row)
        row["resolved_company"] = resolved
        job_tokens = normalize_company(resolved)
        if not job_tokens or not (job_tokens & profile_tokens):
            reject(row, "COMPANY_NOT_IN_PROFILE")

    sli_observe(prev_data, MODULE_NAME, start_time, trace_id)
    return ExecutionResult(
        trace_id=trace_id,
        script_span_id=f"{MODULE_NAME}_{trace_id}",
        data=passed(prev_data),
        artifacts={},
        metrics={},
    )

"""Title matching: every word of a profile title must appear in the job title."""

from __future__ import annotations

import re

_SPLIT_RE = re.compile(r"[\s\-/|.,&()+]+")


def title_words(title: str) -> frozenset[str]:
    """Lowercase word tokens; strip a trailing plural 's' on words longer than 3 chars."""
    tokens = set()
    for w in _SPLIT_RE.split(title.lower()):
        if not w:
            continue
        if len(w) > 3 and w.endswith("s"):
            w = w[:-1]
        tokens.add(w)
    return frozenset(tokens)


def matched_titles(job_title: str, profile_titles: list[str]) -> list[str]:
    """Return every profile title whose every word is present in the job title."""
    job_words = title_words(job_title)
    matched: list[str] = []
    for pt in profile_titles:
        pt_words = title_words(pt)
        if pt_words and pt_words <= job_words:
            matched.append(pt)
    return matched
